    .map((def) => def.id)
    .sort();

  const pooled = collectEquipPoolsFromLootTables();
  const missing = allEquipmentIds.filter((id) => !pooled.has(id));

  assertEquals(
    missing,
    [],
    `Found equipment ids missing from loot table equip pools: ${missing.join(", ")}`
  );
});

