  tiles.fill(TILE_WALL);
  for (let y = 2; y < 12; y++) {
    for (let x = 2; x < 12; x++) {
      tiles[y * CHUNK_SIZE + x] = TILE_FLOOR;
    }
  }

  const chunk = {
